EXEC sp_addextendedproperty @name=N'MS_Description', @value=N'Active | Inactive. Deliberately NO CompanyID on this table: every price in a list points at a Product that already carries its company, so a column here would only be an administrative guardrail - and it would force a group-wide member rate to be duplicated per company.', @level0type=N'SCHEMA', @level0name=N'__mj_BizAppsOrders', @level1type=N'TABLE', @level1name=N'PriceList', @level2type=N'COLUMN', @level2name=N'Status';
