)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [ID],
            [SuccessorProductID],
            [ID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [${flyway:defaultSchema}].[Product]
        WHERE
            [ID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

