            c.[ID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [${flyway:defaultSchema}].[Product] c
        INNER JOIN
            CTE_RootParent p ON c.[ID] = p.[SuccessorProductID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [SuccessorProductID] IS NULL
    ORDER BY
        [RootParentID]
);
