CREATE FUNCTION [${flyway:defaultSchema}].[fnPaymentHeaderReversesPaymentHeaderID_GetRootID]
(
    @RecordID uniqueidentifier,
    @ParentID uniqueidentifier
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [ID],
            [ReversesPaymentHeaderID],
            [ID] AS [RootParentID],
            0 AS [Depth]
        FROM
            [${flyway:defaultSchema}].[PaymentHeader]
        WHERE
            [ID] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[ID],
            c.[ReversesPaymentHeaderID],
            c.[ID] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [${flyway:defaultSchema}].[PaymentHeader] c
        INNER JOIN
            CTE_RootParent p ON c.[ID] = p.[ReversesPaymentHeaderID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [ReversesPaymentHeaderID] IS NULL
    ORDER BY
        [RootParentID]
);
